{"command":"python3 -c "
import csv

with open('outputs/t02_eurostat_raw.csv', 'r', newline='') as f:
    reader = csv.reader(f)

    # Check for any issues
    row_num = 0
    for row in reader:
        row_num += 1
        # Check if any field contains commas (should be quoted)
        for i, field in enumerate(row):
            if ',' in field:
                print(f'Row {row_num}, field {i}: contains comma: {repr(field)}')
            if '\"' in field:
                print(f'Row {row_num}, field {i}: contains quote: {repr(field)}')
        if row_num > 100:
            break

    print(f'Checked first {row_num} rows')
"
